/* Task-focused review: creation and configuration are available on demand. */
body[data-workspace=animation][data-animation-state=review] .work-grid{grid-template-columns:minmax(0,1fr) 312px}
body[data-workspace=animation] .inspector{display:block}
body[data-workspace=animation] .inspector>.tool-disclosure:first-child{margin-top:0}
body[data-workspace=animation] .intro{margin-bottom:8px}
body[data-workspace=animation] .intro h1{margin:6px 0;font-size:26px}
body[data-workspace=animation] .stage{min-height:180px}
body[data-workspace=animation] .pet-image{width:160px;height:160px}
body[data-workspace=animation] .stage-foot{gap:8px}
body[data-workspace=animation] .timeline{padding-top:12px}
body[data-workspace=animation] .timeline-header{margin-bottom:8px}
body[data-workspace=animation] .timeline-settings{flex-direction:column}
body[data-workspace=animation] .timeline-settings>.field{width:100%}
body[data-workspace=animation][data-animation-state=create] .work-grid{grid-template-columns:minmax(0,1fr) 312px}
.selected-frame-tools .tool-disclosure{margin:10px 0 0;padding:8px 10px}
.selected-frame-tools .tool-disclosure button{margin:10px 8px 0 0}
.selected-frame-tools .frame-tools{flex-wrap:wrap}
.frame-tools button,.frame-tools select{min-height:40px;font-size:12px}
.endpoint-lock{min-height:36px;font-size:11px}
.timeline-review{margin-top:8px;padding-top:10px}
#save-status{display:inline;line-height:1.4}
.animation-review footer{position:sticky;bottom:-24px;z-index:3;padding:12px;background:white}
@media(max-width:1050px){
 body[data-workspace=animation][data-animation-state=review] .work-grid,
 body[data-workspace=animation][data-animation-state=create] .work-grid{grid-template-columns:1fr}
}
@media(max-width:680px){
 .topbar{height:auto;flex-wrap:wrap}
 .header-actions{flex-wrap:wrap;width:100%}
 #save-status{display:block;width:100%;font-size:11px}
 .panel-head .tool-disclosure{width:auto}
 body[data-workspace=animation] .stage-foot>.button{width:auto;margin-left:auto}
 body[data-workspace=animation] .stage{min-height:170px}
 body[data-workspace=animation] .stage-foot .playbar{flex-wrap:wrap}
 .animation-review footer{bottom:-16px}
}

