/* Compact bilingual subtitles: Chinese and English share the same line. */
.context-group h2, .panel-head h2, .dialog-head h2, .tool-disclosure > summary,
.field-label, .timeline-header b, .selected-frame-tools h3 {
  word-break: normal;
  overflow-wrap: anywhere;
  line-height: 1.45;
}
.context-group h2, .tool-disclosure > summary { font-size: 13px; }
.field-label { font-size: 12px; letter-spacing: 0; }
.fine-print, .field-hint, .muted, .intro p { line-height: 1.6; letter-spacing: 0; }
.context-group h2 { margin-bottom: 10px; }
.timeline-header { flex-wrap: wrap; gap: 4px 12px; }

/* Bilingual main titles stay inline and wrap only on narrow screens. */
.intro h1 { font-size: clamp(22px, 2.3vw, 32px); line-height: 1.4; letter-spacing: 0; overflow-wrap: anywhere; }

/* Unified Chinese and Latin UI font; source and license in assets/fonts/. */
@font-face{font-family:"Petform Fusion Pixel";src:url("data:font/woff2;base64,") format("woff2");font-weight:400;font-style:normal;font-display:swap}
body.pixel-fantasy, body.pixel-fantasy * {
  font-family: var(--pf-font, "Petform Fusion Pixel", "Segoe UI", sans-serif) !important;
  font-synthesis: none;
}
body.pixel-fantasy :is(h1,h2,h3,h4,strong,b,button,summary,.field-label) { font-weight:400; }
body.pixel-fantasy :is(.fine-print,.field-hint,.muted,.stage-caption,.routine,.preview-speed) { font-size:12px; line-height:1.6; }
body.pixel-fantasy .intro h1 { font-size:24px; line-height:1.5; }
body.pixel-fantasy :is(.context-group h2,.field-label,.tool-disclosure > summary) { font-size:12px; line-height:1.5; }

/* Keep the single animation action directly accessible. */
.pixel-fantasy .animation-preview-head #duplicate-action { margin:0; flex:0 0 auto; font-size:12px; padding:8px 12px; }

/* Paired Liblib credentials stay compact without a disclosure. */
.liblib-credentials { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
@media(max-width:560px) { .liblib-credentials { grid-template-columns:1fr; gap:0; } }

